const guardianPantherSheet=new Image();guardianPantherSheet.assetSrc='assets/guardian-panther-v2.png';
function guardianPantherClip(from,to,max=320){let dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy),reach=Math.min(max,len),end={...from};for(let n=6;n<reach+6;n+=6){let d=Math.min(n,reach),q={x:from.x+dx/(len||1)*d,y:from.y+dy/(len||1)*d};if(!passable(q.x,q.y,22)||!lineClear(end,q,22))break;end=q;}return end;}
function beginGuardianPanther(e){let side=e.pantherSide===1?-1:1;e.pantherSide=side;e.state='walk';e.elapsed=0;e.struck=false;e.attack={pattern:'guardianOrbitPounce',bespoke:true,windup:2.1,center:{x:p.x,y:p.y},radius:dist(e,p),startAngle:Math.atan2(e.y-p.y,e.x-p.x),side,orbitTime:0,last:{x:e.x,y:e.y},locked:false,hit:false};}
function guardianPantherOrbit(e,time){let a=e.attack,to=Math.min(1,time);while(a.orbitTime<to){let t=Math.min(to,a.orbitTime+.01),angle=a.startAngle+a.side*Math.PI/2*t,q={x:a.center.x+Math.cos(angle)*a.radius,y:a.center.y+Math.sin(angle)*a.radius};a.orbitTime=t;if(a.orbitBlocked)continue;if(!passable(q.x,q.y,22)||!lineClear(e,q,22)){a.orbitBlocked=true;continue;}let dx=q.x-e.x,dy=q.y-e.y;e.facing=dx-dy<0?-1:1;e.x=q.x;e.y=q.y;}a.last={x:e.x,y:e.y};}
const guardianPantherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r9e5')return guardianPantherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='guardianOrbitPounce'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=260&&clear){beginGuardianPanther(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,130*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.locked){guardianPantherOrbit(e,e.elapsed);if(e.elapsed>=1){a.locked=true;a.origin={x:e.x,y:e.y};a.target=guardianPantherClip(a.origin,p);e.state='attack';e.facing=a.target.x-e.x-(a.target.y-e.y)<0?-1:1;}}
 if(a.locked&&e.elapsed>=1.7){let t=Math.min(1,(e.elapsed-1.7)/.4),q={x:a.origin.x+(a.target.x-a.origin.x)*t,y:a.origin.y+(a.target.y-a.origin.y)*t};if(!a.jumpBlocked){let next=guardianPantherClip(e,q);if(dist(next,q)>.01)a.jumpBlocked=true;e.x=next.x;e.y=next.y;}a.last={x:e.x,y:e.y};if(e.elapsed>=2.1&&!a.hit){a.hit=true;e.struck=true;if(dist(e,p)<=60&&lineClear(e,p))hurt(92);playSound('impact',e.x,e.y);}}
 if(e.elapsed>=3.2){e.attack=null;e.state='idle';e.t=2.7;}
};
const guardianPantherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r9e5'||!guardianPantherSheet.complete||!guardianPantherSheet.naturalWidth||!guardianPantherSheet.naturalHeight)return guardianPantherDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),lift=0;if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='guardianOrbitPounce'){if(e.elapsed>=1)f={row:2,col:e.elapsed<1.4?0:e.elapsed<1.7?1:e.elapsed<2.1?2:3};if(e.elapsed>=1.7&&e.elapsed<2.1)lift=32*Math.sin(Math.PI*(e.elapsed-1.7)/.4);}let q=project(e.x,e.y),sw=guardianPantherSheet.naturalWidth/4,sh=guardianPantherSheet.naturalHeight/3,w=270,h=w*sh/sw,anchor=[[.83,.83,.83,.83],[.78,.79,.78,.78],[.77,.77,.59,.79]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-lift);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,guardianPantherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(guardianPantherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const guardianPantherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r9e5'?175:guardianPantherSizeBase(e);
const guardianPantherGroundBase=drawGroundEffects;drawGroundEffects=()=>{guardianPantherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r9e5'):enemies)){let a=e.attack;if(e.species!=='r9e5'||e.hp<=0||a?.pattern!=='guardianOrbitPounce'||!visibleAt(e.x,e.y))continue;if(a.locked){if(e.elapsed<2.1){groundRing(a.target.x,a.target.y,60,'#f5d080',3);groundRing(a.target.x,a.target.y,60*Math.max(0,(2.1-e.elapsed)/1.1),'#e4b565',1);}else if(e.elapsed<2.4)groundRing(e.x,e.y,60,'#f5d080',4);}else{groundRing(e.x,e.y,24,'#79d9bd',2);}}};

if(typeof registerDirectEnemy==='function')registerDirectEnemy('r9e5',animateEnemy,drawRegionEnemy);
